#include <bits/stdc++.h>
using namespace std;
const int MAX_LIMIT=510;
typedef pair<int,int> PairType;
#define make_pair mp
#define get_first fi
#define get_second se

int totalN, totalM, modVal, comb[MAX_LIMIT][MAX_LIMIT];
PairType dpTable[MAX_LIMIT][MAX_LIMIT];

int rangeSum(int start, int end) {
    return (start + end) * (end - start + 1) / 2;
}

int addModulo(int a, int b) {
    int sum=a+b;
    if(sum>=modVal) sum-=modVal;
    return sum;
}

PairType operator+(const PairType &a, const PairType &b) {
    return make_pair(addModulo(a.get_first, b.get_first), addModulo(a.get_second, b.get_second));
}

PairType operator*(const PairType &a, const PairType &b) {
    long long firstPart=1LL*a.get_first*b.get_first%modVal;
    long long secondPart=(1LL*a.get_first*b.get_second+1LL*a.get_second*b.get_first)%modVal;
    return make_pair((int)firstPart, (int)secondPart);
}

int main() {
#ifdef LOCAL
    freopen("a.in","r",stdin);
    freopen("a.out","w",stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>totalN>>totalM>>modVal;
    for(int i=0;i<MAX_LIMIT;i++) {
        comb[i][0]=1;
        for(int j=1;j<=i;j++) comb[i][j]=addModulo(comb[i-1][j], comb[i-1][j-1]);
    }
    for(int i=0;i<=totalN;i++) {
        dpTable[i][0]=make_pair(1,0);
        for(int j=1;j<=i && j<=totalM;j++) {
            if(i!=j) {
                for(int k=1;k<=i;k++)
                    dpTable[i][j]=dpTable[i][j]+dpTable[k-1][k-1]*dpTable[i-k][j-k+1]*make_pair(comb[j][k-1],0);
            } else {
                for(int k=1;k<=i;k++) {
                    auto t1=dpTable[k-1][k-1];
                    auto t2=dpTable[i-k][i-k];
                    auto combi=make_pair(comb[i-1][k-1],0);
                    int factor= i+1 - rangeSum(1,k) + rangeSum(k+1,i) - k*(i-k);
                    auto factor_pair=make_pair(factor,0);
                    dpTable[i][j]=dpTable[i][j]+t1*t2*combi*factor_pair;
                }
            }
        }
    }
    cout<<dpTable[totalN][totalM].second;
    return 0;
}
